import app from 'flarum/forum/app';
import Button from 'flarum/common/components/Button';
import Avatar from 'flarum/common/components/Avatar';
import Link from 'flarum/common/components/Link';
import humanTime from 'flarum/common/helpers/humanTime';
import extractText from 'flarum/common/utils/extractText';
import richText from '../text';
import { t } from '../util';

/**
 * The comments on a build, or on one of its log entries (attrs.entry). The
 * list is the page's (attrs.state.comments), so a comment shows wherever it
 * belongs as soon as it is posted.
 */
export default class Comments {
  oninit() {
    this.body = '';
    this.saving = false;
    this.editing = null;
  }
  oncreate(vnode) {
    // A notification about this comment: scroll to it once it is drawn.
    const wanted = m.route.param('comment');
    const node = wanted && vnode.dom.querySelector(`[data-comment="${CSS.escape(wanted)}"]`);
    if (node) setTimeout(() => node.scrollIntoView({
      block: 'center',
      behavior: 'smooth'
    }), 300);
  }
  view(vnode) {
    const {
      build,
      entry,
      state
    } = vnode.attrs;
    const entryId = entry ? Number(entry.id()) : null;
    const comments = state.comments.filter(c => (c.entryId() || null) === entryId);
    return m("div", {
      className: 'GarageComments' + (entry ? ' GarageComments--entry' : '')
    }, comments.length ? m("ul", {
      className: "GarageComments-list"
    }, comments.map(comment => this.comment(comment, state))) : null, build.canComment() ? this.form(vnode.attrs) : !app.session.user && build.published() ? m("p", {
      className: "GarageComments-signin"
    }, m(Button, {
      className: "Button Button--link",
      onclick: () => app.modal.show(() => flarum.reg.asyncModuleImport('flarum/forum/components/LogInModal'))
    }, t('comment.sign_in'))) : null);
  }
  comment(comment, state) {
    const user = comment.user();
    const editing = this.editing === comment;
    return m("li", {
      className: "GarageComment",
      key: comment.id(),
      "data-comment": comment.id()
    }, m(Avatar, {
      user: user,
      className: "GarageComment-avatar"
    }), m("div", {
      className: "GarageComment-main"
    }, m("div", {
      className: "GarageComment-header"
    }, user ? m(Link, {
      className: "GarageComment-author",
      href: app.route.user(user)
    }, user.displayName()) : null, m("span", {
      className: "GarageComment-time"
    }, humanTime(comment.createdAt())), comment.editedAt() ? m("span", {
      className: "GarageComment-edited"
    }, t('comment.edited')) : null), editing ? m("div", {
      className: "GarageComment-editor"
    }, m("textarea", {
      className: "FormControl",
      rows: "3",
      value: this.draft,
      maxlength: "2000",
      "aria-label": extractText(t('comment.edit')),
      oninput: e => this.draft = e.target.value
    }), m("div", {
      className: "GarageComment-actions"
    }, m(Button, {
      className: "Button Button--primary",
      loading: this.saving,
      disabled: !this.draft.trim(),
      onclick: () => this.saveEdit(comment)
    }, t('comment.save')), m(Button, {
      className: "Button",
      onclick: () => this.editing = null
    }, t('comment.cancel')))) : m("div", {
      className: "GarageComment-body"
    }, richText(comment.body())), !editing && (comment.canEdit() || comment.canDelete()) ? m("div", {
      className: "GarageComment-tools"
    }, comment.canEdit() ? m(Button, {
      className: "Button Button--link",
      onclick: () => {
        this.editing = comment;
        this.draft = comment.body();
      }
    }, t('comment.edit')) : null, comment.canDelete() ? m(Button, {
      className: "Button Button--link",
      onclick: () => this.remove(comment, state)
    }, t('comment.delete')) : null) : null));
  }
  form({
    build,
    entry,
    state
  }) {
    return m("form", {
      className: "GarageComments-form",
      onsubmit: e => {
        e.preventDefault();
        this.post(build, entry, state);
      }
    }, m(Avatar, {
      user: app.session.user,
      className: "GarageComment-avatar"
    }), m("div", {
      className: "GarageComments-field"
    }, m("textarea", {
      className: "FormControl",
      rows: this.body ? 3 : 1,
      maxlength: "2000",
      value: this.body,
      placeholder: extractText(t(entry ? 'comment.placeholder_entry' : 'comment.placeholder')),
      "aria-label": extractText(t('comment.label')),
      oninput: e => this.body = e.target.value,
      onkeydown: e => {
        // Ctrl/Cmd + Enter posts. A block, not `cond && …`: a handler returning false cancels every key.
        if (e.key === 'Enter' && (e.metaKey || e.ctrlKey)) {
          e.preventDefault();
          this.post(build, entry, state);
        }
      }
    }), this.body ? m(Button, {
      type: "submit",
      className: "Button Button--primary",
      loading: this.saving,
      disabled: !this.body.trim()
    }, t('comment.post')) : null));
  }
  post(build, entry, state) {
    if (!this.body.trim() || this.saving) return;
    this.saving = true;
    app.store.createRecord('garage-comments').save({
      body: this.body,
      entryId: entry ? Number(entry.id()) : null,
      relationships: {
        build
      }
    }).then(comment => {
      state.comments.push(comment);
      build.pushAttributes({
        commentCount: (build.commentCount() || 0) + 1
      });
      if (entry) entry.pushAttributes({
        commentCount: (entry.commentCount() || 0) + 1
      });
      this.body = '';
    }).finally(() => {
      this.saving = false;
      m.redraw();
    });
  }
  saveEdit(comment) {
    this.saving = true;
    comment.save({
      body: this.draft
    }).then(() => this.editing = null).finally(() => {
      this.saving = false;
      m.redraw();
    });
  }
  remove(comment, state) {
    if (!confirm(extractText(t('comment.delete_confirm')))) return;
    comment.delete().then(() => {
      state.comments = state.comments.filter(c => c !== comment);
      m.redraw();
    });
  }
}
flarum.reg.add('ernestdefoe-garage', 'forum/components/Comments', Comments);