import app from 'flarum/forum/app';
import Button from 'flarum/common/components/Button';
import Icon from 'flarum/common/components/Icon';
import extractText from 'flarum/common/utils/extractText';
import Comments from './Comments';
import { PhotoGrid } from './Lightbox';
import { openEntryEditor } from './openers';
import richText from '../text';
import { t, money } from '../util';

/** "Mar 4, 2026", from the entry's date (a day, no time zone). */
function day(date) {
  const [y, mo, d] = String(date).slice(0, 10).split('-').map(Number);
  return new Date(y, mo - 1, d);
}

/**
 * The build log: newest first, as a timeline. Each entry has its photos, its
 * cost and its own comments (folded until opened).
 */
export default class BuildLog {
  oninit() {
    this.open = new Set();
    const wanted = m.route.param('entry');
    if (wanted) this.open.add(String(wanted));
  }
  oncreate(vnode) {
    const wanted = m.route.param('entry');
    const node = wanted && vnode.dom.querySelector(`[data-entry="${CSS.escape(wanted)}"]`);
    if (node) setTimeout(() => node.scrollIntoView({
      block: 'start',
      behavior: 'smooth'
    }), 300);
  }
  view(vnode) {
    const {
      build,
      state
    } = vnode.attrs;
    const entries = state.entries;
    if (!entries.length) {
      return m("div", {
        className: "GarageLog-empty"
      }, m(Icon, {
        name: "fas fa-clock-rotate-left"
      }), m("p", null, t(build.canEdit() ? 'build.no_updates_own' : 'build.no_updates')), build.canEdit() ? m(Button, {
        className: "Button Button--primary",
        icon: "fas fa-plus",
        onclick: () => openEntryEditor({
          build,
          log: state
        })
      }, t('build.add_update')) : null);
    }
    return m("div", {
      className: "GarageLog"
    }, m("ol", {
      className: "GarageLog-list"
    }, entries.map(entry => this.entry(entry, build, state))), state.moreEntries ? m("div", {
      className: "GarageLog-more"
    }, m(Button, {
      className: "Button",
      loading: this.loading,
      onclick: () => this.loadMore(build, state)
    }, t('build.older_updates'))) : null);
  }
  entry(entry, build, state) {
    const date = day(entry.happenedOn());
    const open = this.open.has(entry.id());
    const count = entry.commentCount() || 0;
    return m("li", {
      className: "GarageLog-entry",
      key: entry.id(),
      "data-entry": entry.id()
    }, m("div", {
      className: "GarageLog-date",
      "aria-hidden": "true"
    }, m("span", {
      className: "GarageLog-month"
    }, dayjs(date).format('MMM')), m("span", {
      className: "GarageLog-day"
    }, dayjs(date).format('D')), m("span", {
      className: "GarageLog-year"
    }, dayjs(date).format('YYYY'))), m("article", {
      className: "GarageLog-card"
    }, m("header", {
      className: "GarageLog-header"
    }, m("h3", {
      className: "GarageLog-title"
    }, entry.title()), m("time", {
      className: "GarageLog-when",
      datetime: entry.happenedOn()
    }, dayjs(date).format('LL')), entry.cost() ? m("span", {
      className: "GarageLog-cost"
    }, m(Icon, {
      name: "fas fa-coins"
    }), " ", money(entry.cost())) : null), entry.body() || entry.bodyHtml() ? m("div", {
      className: "GarageLog-body"
    }, richText(entry.body(), entry.bodyHtml())) : null, m(PhotoGrid, {
      photos: entry.photos(),
      caption: entry.title(),
      limit: 5
    }), m("footer", {
      className: "GarageLog-footer"
    }, build.published() ? m(Button, {
      className: "Button Button--link",
      icon: "far fa-comment",
      "aria-expanded": open ? 'true' : 'false',
      onclick: () => open ? this.open.delete(entry.id()) : this.open.add(entry.id())
    }, count ? t('entry.comments', {
      count
    }) : t('entry.reply')) : null, entry.canEdit() ? m('[', null, m(Button, {
      className: "Button Button--link",
      icon: "fas fa-pen",
      onclick: () => openEntryEditor({
        build,
        entry,
        log: state
      })
    }, t('entry.edit')), m(Button, {
      className: "Button Button--link",
      icon: "far fa-trash-alt",
      onclick: () => this.remove(entry, build, state)
    }, t('entry.delete'))) : null), open && build.published() ? m(Comments, {
      build: build,
      entry: entry,
      state: state
    }) : null));
  }
  loadMore(build, state) {
    this.loading = true;
    app.store.find('garage-entries', {
      filter: {
        build: build.id()
      },
      page: {
        offset: state.entries.length,
        limit: 20,
        total: 0
      }
    }).then(more => {
      state.entries = [...state.entries, ...more];
      state.moreEntries = !!more.payload?.links?.next;
    }).finally(() => {
      this.loading = false;
      m.redraw();
    });
  }
  remove(entry, build, state) {
    if (!confirm(extractText(t('entry.delete_confirm', {
      title: entry.title()
    })))) return;
    entry.delete().then(() => {
      state.entries = state.entries.filter(e => e !== entry);
      // The build's counts, latest entry and spend were worked out again on the server.
      app.store.find('garage-builds', build.id());
      m.redraw();
    });
  }
}
flarum.reg.add('ernestdefoe-garage', 'forum/components/BuildLog', BuildLog);